const parts: Record<string, string> = {n: "noun", v: "verb", a: "adjective", r: "adverb"};
export const thousandVocabulary = Object.entries(thousandWordGroups).flatMap(([topic, text]) =>
  text.split("\n").map(line => {
    const [word, part, meaning, bengali, exampleSentence, phrases] = line.split("|");
    if (!parts[part] || !phrases) throw new Error(`Incomplete vocabulary entry: ${word}`);
    return {word, topic, part: parts[part], meaning, bengali, exampleSentence,
      collocations: phrases.split(";"), synonyms: [] as string[], level: "Intermediate",
      usageNote: "Practise the word in its example and collocations. Words can have other meanings in other contexts."};
  })
);
